with q as (select * from (values ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law2250-group2-art18-03','Lei nº 2.250/2009 — art. 18, Grupo Ocupacional 2','Para fins de promoção do antigo Grupo Ocupacional 2, no qual estavam Agente e Escrivão, qual regra específica aparece no art. 18 da Lei nº 2.250/2009 para a passagem às classes posteriores à Classe II?','(A) Exigência obrigatória de doutorado.\n(B) Trabalho com sugestão de melhoria dos serviços da área de atuação, com temas definidos pela comissão de promoção.\n(C) Proposta de melhoria da segurança pública estadual para todas as classes.\n(D) Prova oral anual.\n(E) Cinco anos de exercício em cada classe.','B','O art. 18, relativo ao Grupo Ocupacional 2, prevê trabalho com sugestão de melhoria dos serviços da área de atuação, com temas definidos pela comissão. Não se deve transportar automaticamente os requisitos do art. 17, que trata do Grupo Ocupacional 1.'), ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law2250-progression-promotion-04','Lei nº 2.250/2009 — progressão x promoção','Um Oficial Investigador passa da Referência 2 para a Referência 3, permanecendo na Classe II. Esse movimento é classificado como:','(A) Promoção.\n(B) Progressão.\n(C) Reenquadramento de cargo.\n(D) Investidura.\n(E) Promoção à Classe Especial.','B','O art. 15 define progressão como a passagem para a referência imediatamente superior dentro da mesma classe. Promoção é a elevação para a referência inicial da classe imediatamente superior, conforme art. 16.')) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)) insert into public.curated_question_catalog (source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,difficulty,content_status,is_original,state,career_category,role_type,tested_topic,import_content_key,import_unique_key,didactic_provenance) select '43712f0d-aad2-48b5-a685-6937551f2d74','d204d14f-8aa6-4c57-92ad-3fb3c3e901f1',external_item_key,'Norte Concursos — treino autoral PC-AC 2026',2026,'Oficial Investigador de Polícia','AUTORAL','Legislação Institucional',subtopic,question_text||E'\n\n'||options_text,answer,explanation,'média','active',true,'AC','Polícia Civil','Oficial Investigador de Polícia',subtopic,external_item_key,'pcac-2026-'||external_item_key,jsonb_build_object('kind','didactic_original','authored',true,'target_exam','PC-AC 2026 — Oficial Investigador de Polícia','not_official_exam',true,'license_note','Questão autoral inédita; não é item oficial da IDECAN','linked_study_material_slug',material_slug,'source_material_slug',material_slug,'source_exam_reference','Edital nº 001 SEAD/PCAC, de 05/11/2026, Anexo III') from q on conflict (source_id,external_item_key) do update set question_text=excluded.question_text,official_answer=excluded.official_answer,explanation=excluded.explanation,didactic_provenance=excluded.didactic_provenance,content_status='active',subtopic=excluded.subtopic;